SELECT CASE WHEN s.rating >= 3.6 THEN 'high' WHEN s.rating >= 1.8 THEN 'mid' ELSE 'low' END AS rating_bucket, s.city, SUM(p.stock_qty) AS total_stock_qty FROM products p RIGHT JOIN suppliers s ON p.supplier_id = s.id GROUP BY CASE WHEN s.rating >= 3.6 THEN 'high' WHEN s.rating >= 1.8 THEN 'mid' ELSE 'low' END, s.city
